// The same three questions the agent gets, so the two runs can be compared on answers and on tokens.
// No tools on this path: whatever the model says here, it said from memory.
const questions = [
  'A 1 hour 52 minute feature at 22.7 Mbps. How many gigabytes is the mezzanine file, and how many minutes does the transfer take at 185 Mbps?',
  'What is the status and deadline of TT-0142, and is it on Max or Discovery+?',
  'How long will the mezzanine for TT-0142 take to transfer at 150 Mbps?',
];
return questions.map((q, i) => ({ json: { n: i + 1, question: q } }));
